fn rotate(a: &[i32], offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }
    // Compute the effective rotation within [0, n)
    let k = offset % n;
    // Build the rotated array by taking the tail [k..n) then the head [0..k)
    a[k..]
        .iter()
        .chain(&a[..k])
        .cloned()
        .collect()
}

